  "여러 AI CLI(Claude Code·Codex·Gemini CLI·Hermes)와 OpenAI 호환 API를 한 화면에서 팀으로 묶어 쓰는 로컬 앱이야. 서버는 이 PC(127.0.0.1)에서만 열리고, 런타임 의존성이 없어 가벼워.": "这是一款本地应用，可以把多个 AI CLI（Claude Code、Codex、Gemini CLI、Hermes）和 OpenAI 兼容 API 组成团队，在一个界面中使用。服务器只在本机（127.0.0.1）开放，没有运行时依赖，十分轻量。",
