  "{from} 사용량 한도에 걸려서 {to}({model})가 이어받아 계속해.": "{from} 已达到用量上限，由 {to}（{model}）接手继续。",
  "{from} 사용량이 거의 다 차서 이번엔 {to}({model})가 맡아.": "{from} 的用量快用完了，这次由 {to}（{model}）负责。",
