  "구독 로그인": "订阅登录",
  "내 구독으로 실행해. PC에 {name} 환경변수가 있어도 무시해서 뜻밖의 API 과금을 막아.": "使用你的订阅运行。即使电脑上有 {name} 环境变量也会忽略，避免意外的 API 计费。",
  "공식 API 키로 실행해(사용한 만큼 과금). 키는 API 키 탭에 넣어.": "使用官方 API 密钥运行（按用量计费）。请在 API 密钥标签页中填写密钥。",
  "키 넣으러 가기": "去填写密钥",
  "Claude Code · Codex 공식 API 키": "Claude Code · Codex 官方 API 密钥",
  "AI 계정 탭에서 결제 방식을 API 키로 고른 AI만 이 키를 써. 비우면 PC 환경변수의 키를 써.": "只有在 AI 账号标签页中把计费方式设为 API 密钥的 AI 才会使用这些密钥。留空则使用电脑环境变量中的密钥。",
  "Anthropic API 키 (Claude Code)": "Anthropic API 密钥（Claude Code）",
  "발급: platform.claude.com → API Keys": "获取：platform.claude.com → API Keys",
