  "ACP 에이전트 (Agent Client Protocol)": "ACP 智能体（Agent Client Protocol）",
  "ACP 표준을 지원하는 코딩 에이전트를 그대로 붙여. 에이전트 편집에서 AI를 ACP 에이전트로 고르고, 모델 칸에서 여기 추가한 에이전트를 골라. 로그인·요금은 각 에이전트 규정을 따라.": "直接接入支持 ACP 标准的编程智能体。在智能体编辑中把 AI 设为 ACP 智能体，并在模型栏选择这里添加的智能体。登录与费用遵循各智能体自己的规定。",
  "인자(띄어쓰기로 구분)": "参数（用空格分隔）",
  "설치됨": "已安装",
  "새 ACP 에이전트": "新的 ACP 智能体",
  "직접 추가": "手动添加",
  "ACP 에이전트": "ACP 智能体",
  "Agent Client Protocol 표준 · Gemini CLI·Hermes·OpenCode·Goose 등": "Agent Client Protocol 标准 · Gemini CLI、Hermes、OpenCode、Goose 等",
  "설정 → API 키·로컬 모델 → ACP 에이전트에서 추가해줘": "请在 设置 → API 密钥·本地模型 → ACP 智能体 中添加",
  "추가한 ACP 에이전트 명령을 찾을 수 없어. 설치했는지 확인해줘.": "找不到已添加的 ACP 智能体命令。请确认是否已安装。",
  "쓸 ACP 에이전트가 없어. 설정 → API 키·로컬 모델 → ACP 에이전트에서 추가해줘.": "没有可用的 ACP 智能体。请在 设置 → API 密钥·本地模型 → ACP 智能体 中添加。",
  "권한 설정에 따라 거부: {name}": "根据权限设置已拒绝：{name}",
  "작업 폴더 밖의 파일은 읽을 수 없어.": "无法读取工作文件夹之外的文件。",
  "읽기 전용 권한이라 파일을 쓸 수 없어.": "只读权限，无法写入文件。",
  "작업 폴더 밖에는 쓸 수 없어.": "无法写入工作文件夹之外。",
