  "계정 사용 원칙 보기": "查看账号使用原则",
  "계정 사용 원칙": "账号使用原则",
  "오피스 크루는 내 PC에 설치·로그인한 공식 CLI를 그대로 실행해. 로그인 토큰은 읽지도, 저장하지도, 다른 곳으로 보내지도 않아.": "Office Crew 原样运行你在电脑上安装并登录的官方 CLI。它从不读取、保存或向别处发送登录令牌。",
  "구독 로그인은 내 PC에서 나 혼자 쓰는 용도야. 계정을 나눠 쓰거나 다른 사람에게 서비스로 제공하지 마.": "订阅登录仅供你本人在自己的电脑上使用。不要共享账号，也不要作为服务提供给他人。",
  "제품을 만들거나 회사에서 쓰거나 사람 없이 돌릴 땐 Claude·Codex 결제 방식을 API 키로 바꿔줘 (설정 → AI 계정).": "如果要做产品、在公司使用或无人值守运行，请把 Claude·Codex 的计费方式改为 API 密钥（设置 → AI 账号）。",
  "Hermes에서 Anthropic을 고르면 Claude Code 로그인을 가져다 쓸 수 있어. 대신 Anthropic API 키나 다른 제공자를 지정해줘.": "如果 Hermes 选择 Anthropic 作为服务商，可能会复用 Claude Code 的登录。请改为指定 Anthropic API 密钥或其他服务商。",
  "약관은 바뀔 수 있고 이 안내는 법률 자문이 아니야. 각 서비스의 최신 약관을 확인해줘.": "条款可能会变化，本说明也不构成法律建议。请查看各服务的最新条款。",
  "자세히 보기": "了解详情",
  "확인했어": "知道了",
  // ── 첫 실행 기본 데이터 (seed.js) ──
  "OpenRouter (Hermes·Grok·DeepSeek 등)": "OpenRouter（Hermes·Grok·DeepSeek 等）",
  "리서처": "调研员",
  "너는 조사 담당이야. 필요한 자료를 찾아 핵심 사실과 출처를 정리해. 확인 안 된 건 \"추정\"이라고 표시해.": "你负责调研。查找所需资料，整理关键事实和出处。未经核实的内容请标注为“推测”。",
  "정리왕": "整理师",
  "너는 정리 담당이야. 앞 단계 결과를 중복 없이 구조화해서 표·목록으로 정리해.": "你负责整理。把上一阶段的结果去重后结构化，整理成表格和列表。",
  "분석가": "分析师",
  "너는 분석 담당이야. 정리된 내용을 근거로 판단·우선순위·위험을 분석하고 실행 계획을 세워.": "你负责分析。根据整理好的内容分析判断、优先级和风险，并制定执行计划。",
  "빌더": "构建师",
  "너는 빌드 담당이야. 분석·계획을 바탕으로 작업 폴더에 실제 결과물을 만들고, 만든 파일과 확인 결과를 보고해.": "你负责构建。根据分析和计划在工作文件夹中做出实际成果，并汇报生成的文件和检查结果。",
  "기본 팀": "默认团队",
  "조사(소네트) → 정리(솔) → 분석(오푸스 하이) → 빌드(오푸스 X하이)": "调研（Sonnet）→ 整理（Sol）→ 分析（Opus 高）→ 构建（Opus 超高）",
  "자동 라우팅 팀": "自动路由团队",
  "로그인된 AI 중에서 역할별 모델·노력을 자동 배정 (조사→정리→분석→빌드→교차 검수)": "从已登录的 AI 中按角色自动分配模型和推理强度（调研→整理→分析→构建→交叉审查）",
  "자동 조사": "自动调研",
  "필요한 자료를 찾아 핵심 사실과 출처를 정리해. 확인 안 된 건 \"추정\"이라고 표시해.": "查找所需资料，整理关键事实和出处。未经核实的内容请标注为“推测”。",
  "자동 정리": "自动整理",
  "앞 단계 결과를 중복 없이 표·목록으로 정리해.": "把上一阶段的结果去重后整理成表格和列表。",
  "자동 분석": "自动分析",
  "근거를 바탕으로 판단·우선순위·위험을 분석하고 실행 계획을 세워.": "根据依据分析判断、优先级和风险，并制定执行计划。",
  "자동 빌드": "自动构建",
  "계획대로 작업 폴더에 실제 결과물을 만들고, 만든 파일과 확인 결과를 보고해.": "按计划在工作文件夹中做出实际成果，并汇报生成的文件和检查结果。",
  "자동 검수": "自动审查",
  "만든 결과를 요구사항 기준으로 검토해 문제·누락·개선점을 목록으로 지적해.": "按需求审查成果，列出问题、遗漏和改进点。",
  // ── 검증 수정 (routing·acp·orchestrator) ──
  "사용률이 기준을 넘어 {time}까지 피하는 중": "用量超过阈值，{time} 前暂不使用",
  "ACP 에이전트 \"{id}\"를 찾을 수 없어. 에이전트 편집의 모델 칸에서 다시 골라줘.": "找不到 ACP 智能体“{id}”。请在智能体编辑的模型栏中重新选择。",
  "{from} 오류가 한도 문구처럼 보이지만, 내 PC 모델 작업은 다른 AI로 넘기지 않아.": "{from} 的错误看起来像用量上限，但指定给本地模型的工作不会转交给其他 AI。",
  // ── 재검증 수정 (index) ──
  "가려진 값({name})을 고치려면 지우고 새로 입력해줘.": "要修改被遮盖的值（{name}），请清空后重新输入。",
  // ── 최종 검증 수정 (index) ──
  "가려진 값은 비밀값 이름으로만 옮길 수 있어. {name}에는 새로 입력해줘.": "被遮盖的值只能移到机密名称下。请为 {name} 重新输入。",
