  "지우기": "移除",
  "투명 배경 PNG를 추천해. 긴 변 256px로 줄여 이 PC에만 저장돼. 작은 도트 그림은 선명하게 확대돼.": "建议使用透明背景的 PNG。长边会缩到 256px，只保存在这台电脑上。小的像素画会清晰放大。",
  "내 마을": "我的小镇",
  "마을 꾸미기 (집 그림 바꾸기)": "装扮小镇（更换房子）",
  "크루 마을: 쉬는 에이전트는 자기 집에 들어가 있고, 일을 시작하면 회사로 출근해. 집 그림을 내 그림으로 바꿀 수 있어.": "船员小镇：空闲的代理待在自己家里，开始工作时去公司上班。房子可以换成你自己的图片。",
  "마을 꾸미기": "装扮小镇",
  "집 그림": "房子图片",
  "기본 집으로": "默认房子",
  "쉬는 에이전트가 들어가 있는 집이야. 투명 배경 PNG를 추천해(예: 캡슐·둥지·텐트). 그림은 이 PC에만 저장돼.": "这是空闲代理待着的房子。建议使用透明背景的 PNG（例如胶囊、鸟窝、帐篷）。图片只保存在这台电脑上。",
  "에이전트 모습은 에이전트 편집에서 사람·크리처·내 그림 중에 골라.": "在代理编辑中为每个代理选择外观：人物、小生物或你自己的图片。",
