  "진행자 답에서 목표 카드를 읽지 못해서 요청 글로 카드를 만들었어. 기준을 직접 적어 줘.": "没能从主持人的回答中读出目标卡片，所以用请求生成了卡片。请自己写下标准。",
  "목표 초안 씀": "已写好目标草稿",
  "지금 목표 카드가 아니야. 화면을 새로 보고 다시 해 줘.": "这不是当前的目标卡片。请刷新画面后重试。",
  "이미 처리한 목표 카드야.": "这张目标卡片已经处理过了。",
  "다른 작업이 도는 중이야. 끝난 뒤에 시작해 줘.": "另一项工作正在进行。请等它结束后再开始。",
  "이 카드는 마지막 목표 카드가 아니야.": "这不是最新的目标卡片。",
  "화면에 보이던 카드와 저장된 초안이 달라. 지금 초안을 다시 보여 줄게.": "你画面上的卡片与保存的草稿不一致。将重新显示当前草稿。",
  "목표가 비어 있어.": "目标是空的。",
  "합격 기준이 하나도 없어. \"고쳐서 시작\"으로 기준을 적어 줘.": "一条验收标准都没有。请用“修改后开始”写下标准。",
  "요청 메시지를 찾지 못했어. 요청을 다시 보내 줘.": "找不到请求消息。请重新发送请求。",
  "사용자가 고쳐서 확인했어(기준 {n}개).": "你修改后确认了（{n} 条标准）。",
  "사용자가 목표를 확인했어(기준 {n}개).": "你确认了目标（{n} 条标准）。",
  "사용자가 목표 카드를 닫았어.": "你关闭了目标卡片。",
  "버릴 끊긴 목표가 없어.": "没有可以放弃的已中断目标。",
  "끊긴 목표를 버렸어.": "已放弃中断的目标。",
  "\"{label}\" 단계 시작 · 추가 지시 {n}개 넣음": "“{label}”阶段开始 · 放入了 {n} 条补充指示",
  "\"{label}\" 단계 시작": "“{label}”阶段开始",
  "\"{label}\" 단계 건너뜀": "跳过了“{label}”阶段",
  "\"{label}\" 단계 끝": "“{label}”阶段结束",
  "목표 초안을 쓰다가 멈춰서 이 목표는 닫았어.": "起草目标时停止了，所以这个目标已关闭。",
  "목표 초안을 받지 못해서 이 목표는 닫았어. 요청을 다시 보내 줘.": "没有得到目标草稿，所以这个目标已关闭。请重新发送请求。",
  "실행 오류로 목표를 멈췄어.": "因运行错误，目标已停止。",
  "중지해서 목표를 멈췄어.": "你停止了运行，目标已停止。",
  "{name}이(가) 목표 카드 초안을 쓰기 시작했어.": "{name} 开始起草目标卡片。",
  "첨부 파일": "附件",
  "[확정된 목표와 합격 기준 (사용자가 확인함. 바꾸지 마)]": "[已确定的目标和验收标准（用户已确认。不要更改）]",
  "이 목표와 기준을 채우는 쪽으로 네 단계를 해. 기준을 바꾸거나 범위 밖의 일을 하지 마.": "请朝着满足这个目标和标准的方向完成你的阶段。不要更改标准，也不要做范围之外的事。",
  "[목표 카드 다시 쓰기] 앞 답의 끝에서 목표 카드 블록(oc-goal)을 읽지 못했어. 같은 내용을 아래 형식에 맞춰 블록 하나로 다시 써.": "[重写目标卡片] 没能在你上一个回答的末尾读到目标卡片块（oc-goal）。请按下面的格式把同样的内容重新写成一个块。",
  "이 요청은 \"목표까지\" 모드야. 아직 일을 시작하지 말고, 요청을 목표 카드로 정리해 줘. 사용자가 카드를 확인한 뒤에 팀이 일을 시작해.": "这个请求处于“直到目标”模式。先不要开始工作，请把请求整理成目标卡片。用户确认卡片后团队才开始工作。",
  "목표: 한 줄(200자 안)": "目标：一行（200 字以内）",
  "합격 기준: 2~7개. 일이 끝난 뒤 파일을 열어 보거나 명령을 돌려 맞는지 확인할 수 있는 문장으로(하나에 300자 안)": "验收标准：2~7 条。每条都要是工作完成后可以通过打开文件或运行命令来检查的句子（每条 300 字以内）",
  "범위 밖: 이번에 하지 않을 것(없으면 빈 목록, 5개까지)": "范围之外：这次不做的事（没有就留空列表，最多 5 条）",
  "사용자가 정할 것: 사용자만 정할 수 있는 것(없으면 빈 목록, 5개까지)": "由用户决定的事：只有用户能决定的事（没有就留空列表，最多 5 条）",
  "작업 폴더의 파일은 읽어 봐도 되지만 고치지 마. 코드나 파일에서 알 수 있는 건 묻지 마.": "可以读取工作文件夹里的文件，但不要修改。能从代码或文件里知道的事不要问。",
  "요청이 너무 흐릿해서 카드를 쓸 수 없을 때만 질문 블록으로 사용자에게 물어.": "只有当请求太模糊、写不出卡片时，才用提问块问用户。",
  "답 맨 끝에 아래 블록 하나를 써. 블록 뒤에는 아무것도 쓰지 마.": "在回答的最后写一个下面这样的块。块后面不要写任何东西。",
  "{name}에게 바로 넣은 지시: {text}": "直接发给 {name} 的指示：{text}",
  "바로 넣은 지시: {text}": "直接发出的指示：{text}",
  "목표가 살아 있는 동안에는 팀을 바꿀 수 없어. 목표 카드를 닫거나 끊긴 목표를 버린 뒤에 바꿔 줘.": "目标未结束时不能更换团队。请先关闭目标卡片或放弃已中断的目标。",
  "goalMode 는 true 나 false 여야 해.": "goalMode 必须是 true 或 false。",
  "목표가 살아 있는 동안에는 목표 모드를 끌 수 없어. 목표 카드를 닫거나 끊긴 목표를 버린 뒤에 꺼 줘.": "目标未结束时不能关闭目标模式。请先关闭目标卡片或放弃已中断的目标。",
  "이 카드는 영입 제안이 아니야.": "这张卡片不是招募提议。",
