  "끊김": "已中断",
  "끊긴 목표를 버릴까? 버리면 새 요청을 보낼 수 있어.": "要放弃已中断的目标吗？放弃后就可以发送新的请求。",
  "(비어 있음)": "（空）",
  "기준이 없어. \"고쳐서 시작\"으로 기준을 적어 줘.": "没有标准。请用“修改后开始”写下标准。",
  "사용자가 정할 것": "由你决定的事",
  "목표 카드를 닫았어.": "目标卡片已关闭。",
  "지난 목표": "以前的目标",
  "목표 카드": "目标卡片",
  "사용자 확인": "已由你确认",
  "고쳐서 확인": "修改后确认",
  "사용자 확인 전": "尚未确认",
  "{name}이(가) 쓴 초안이야. 확인해야 팀이 일을 시작해. 아직 아무것도 시작하지 않았어.": "这是 {name} 写的草稿。你确认后团队才会开始工作。目前什么都还没开始。",
  "진행자 답에서 목표 카드를 읽지 못해서 요청 글로 만들었어. 기준을 직접 적어 줘.": "没能从主持人的回答中读出目标卡片，所以用你的请求生成了卡片。请自己写下标准。",
  "진행자가 쓴 초안에 걱정되는 부분이 있어. 확인하기 전에 잘 읽어 봐.": "主持人写的草稿里有让人担心的地方。确认之前请仔细阅读。",
  "저장된 초안으로 다시 그렸어. 다시 확인해 줘.": "已按保存的草稿重新显示。请再确认一次。",
  "목표 (한 줄)": "目标（一行）",
  "합격 기준 (한 줄에 하나, {n}개까지)": "验收标准（每行一条，最多 {n} 条）",
  "범위 밖 (한 줄에 하나)": "范围之外（每行一条）",
  "사용자가 정할 것 (한 줄에 하나)": "由你决定的事（每行一条）",
  "기준 {n}개": "{n} 条标准",
  "{n}개를 넘는 줄은 빠져.": "超过 {n} 条的行会被去掉。",
  "Esc 고치기 취소 · Ctrl+Enter 시작": "Esc 取消修改 · Ctrl+Enter 开始",
  "이 내용으로 시작": "按这个内容开始",
  "고치기 취소": "取消修改",
  "이대로 시작": "按原样开始",
  "고쳐서 시작": "修改后开始",
  "그만": "不要了",
  "아직 목표가 없어. 입력창 옆의 \"목표까지\"를 켜고 요청을 보내면 여기에 과정이 한 줄씩 쌓여.": "还没有目标。打开输入框旁的“直到目标”并发送请求，过程就会在这里一行一行地记录。",
  "(아직 없음)": "（还没有）",
  "에이전트가 씀 · 사용자 확인 전": "由智能体撰写 · 尚未经你确认",
  "아직": "尚未",
  "그 메시지로 가기": "转到那条消息",
  "목표가 도는 동안 보낸 말이라 그 뒤에 시작하는 단계들에 추가 지시로 들어가": "这是目标进行中发送的消息，会作为补充指示放进之后开始的每个阶段",
  "추가 지시": "补充指示",
  "목표 초안": "目标草稿",
  "그 뒤에 시작하는 단계들에 넣을 추가 지시로 받았어": "已作为补充指示，放进之后开始的每个阶段",
  "그 뒤에 시작하는 단계들에 넣을 추가 지시… (Enter)": "给之后开始的各阶段的补充指示…（Enter）",
  "목표로 만들 요청을 적어줘 — 진행자가 먼저 목표 카드를 써": "写下要变成目标的请求——主持人会先写目标卡片",
  "켜면 보낸 요청을 진행자가 먼저 목표 카드(목표·합격 기준)로 만들고, 네가 확인한 뒤에 팀이 그 목표를 들고 일해. @이름으로 보낸 말은 지금처럼 실행돼.": "打开后，主持人会先把你的请求整理成目标卡片（目标和验收标准），你确认后团队再带着这个目标工作。用 @名字 发送的消息照常执行。",
  "목표까지": "直到目标",
  "진행 기록": "进度记录",
  "반영하지 못한 추가 지시가 {n}개 있어.": "有 {n} 条补充指示没能用上。",
  "추가 지시는 목표 하나에 {n}개까지야. 더 보내려면 목표를 멈추고 새 요청으로 보내 줘.": "一个目标最多接收 {n} 条补充指示。要再发送，请停止目标并作为新请求发送。",
  "\"{label}\" 단계 다시 · 추가 지시 {n}개 넣음": "“{label}”阶段重做 · 放入了 {n} 条补充指示",
  "진행자를 건너뛰어서 목표 초안 없이 이 목표는 닫았어. 요청을 다시 보내 줘.": "跳过了主持人，所以没有草稿，这个目标已关闭。请重新发送请求。",
  "살아 있는 목표가 있어서 지금은 보낼 수 없어. 목표 카드를 닫거나 끊긴 목표를 버린 뒤에 다시 해 줘.": "还有未结束的目标，现在无法发送。请先关闭目标卡片或丢弃中断的目标，再试一次。",
  "초안이 바뀌었어. 아래 내용을 확인해 줘. 고치던 글은 그대로 뒀어.": "草稿已变更。请确认下面的内容。你正在修改的文字保留了。",
  "추가 지시로 받았어. 다만 뒤에 시작할 단계가 없어서 이번 목표에는 반영되지 않을 수 있어": "已作为补充指示收到，但后面没有要开始的阶段，这次目标可能用不上它",
  "목표 카드를 쓰는 진행자에게 바로 지시하기… (Enter)": "直接指示正在写目标卡片的主持人…（Enter）",
  "목표 모드를 껐어: {why}": "已关闭目标模式：{why}",
  "통과로 끝": "已通过并结束",
  "통과": "通过",
  "불합격": "不合格",
  "에이전트가 씀 · 사용자 확인 안 함": "由代理撰写 · 用户未确认",
  "이 답에서는 판정 블록을 받지 못했어(판정 없음).": "没有从这条回答中收到判定块（无判定）。",
  "기준 판정": "标准判定",
  "기준 {total}개 중 통과 {pass} · 불합격 {fail} · 확인 못 함 {unknown}": "{total} 条标准：通过 {pass} · 不合格 {fail} · 无法确认 {unknown}",
  "검수: {name}이(가) 기준마다 판정해.": "审查：由 {name} 逐条判定标准。",
  "검수할 다른 팀원이 없어서 판정 없이 끝나고 네게 물어.": "没有其他团队成员可以审查，所以会在没有判定的情况下结束并询问你。",
  "기준 판정으로 대신해서 건너뛰는 단계: {labels}": "由标准判定代替而跳过的阶段：{labels}",
  "기준 {n}개를 모두 통과해서 끝냈어.": "{n} 条标准全部通过，目标已完成。",
  "받아들여서 끝냈어 · 남은 기준 {n}개": "已接受并结束 · 剩余标准 {n} 条",
  "검수자나 건너뛸 단계가 바뀌어서 지금 값으로 다시 그렸어. 다시 확인해 줘.": "审查者或要跳过的阶段已变更，已按当前值重新显示。请再次确认。",
  "남기기": "保留",
  "남겨서 그대로 돌려.": "保留并照常运行。",
  "이 단계는 기준 판정으로 대신해서 건너뛰어.": "此阶段会被跳过，由标准判定代替。",
  "이미 지나간 대기야.": "这个等待已经结束了。",
  "호출 상한": "调用上限",
