  "{n}번 더": "再加 {n} 次",
  "상한을 늘리고 이어서 해.": "提高上限并继续。",
  "반영 안 한 추가 지시가 {n}개 있어. 어떻게 할까?": "有 {n} 条补充指示还没用上。要怎么办？",
  "검수 {r}회차 뒤에 통과하지 못한 기준이 {n}개 남았어. 어떻게 할까?": "第 {r} 次审查后，还有 {n} 条标准没有通过。要怎么办？",
  "판정 없이 기준 {n}개가 남았어. 어떻게 할까?": "有 {n} 条标准没有判定。要怎么办？",
