  "남은 기준": "剩余标准",
  "그대로 끝": "就此结束",
  "받아들이기": "接受",
  "추가 지시는 반영하지 않고 지금 판정으로 끝내.": "不使用补充指示，按当前判定结束。",
  "남은 기준은 판정 그대로 두고 끝내.": "保留剩余标准的判定并结束。",
  "반영해서 한 번 더": "用上它们再来一次",
