  "권한·도구가 없음": "没有权限或工具",
  "다른 일이 먼저": "需先完成其他工作",
  "에이전트가 막힘 블록에 적은 종류야(사용자 확인 안 함).": "这是代理在受阻块中写的类型（用户未确认）。",
  "에이전트가 적음": "代理所写",
  "회의 차례": "会议发言",
  "일 단계": "工作阶段",
  "kind 에는 막힌 까닭 하나를 적어: unclear(지시가 모호함) · input(넘겨받은 것이 틀림) · capability(권한·도구가 없음) · dependency(다른 일이 먼저 끝나야 함). 모르면 빼.": "在 kind 中写一个受阻的原因：unclear（指令不明确）· input（收到的内容有误）· capability（缺少权限或工具）· dependency（需先完成其他工作）。不确定就省略。",
  "밖으로 나가는 일(원격 저장소에 올리기·배포·메일·메시지 보내기·게시·결제)과 작업 폴더 밖의 파일 지우기는 하기 전에 질문 블록으로 물어. 작업 폴더 안에서 고치고 만드는 건 묻지 말고 해.": "凡是会发到外部的事（推送到远程仓库、部署、发送邮件或消息、发布、付款）以及删除工作文件夹之外的文件，做之前先用问题块询问。在工作文件夹内修改和创建不用问。",
  "밖으로 나가는 일(원격 저장소에 올리기·배포·메일·메시지 보내기·게시·결제)과 작업 폴더 밖의 파일 지우기는 하지 마. 필요하면 답에 적어 둬. 작업 폴더 안에서 고치고 만드는 건 그냥 해.": "不要做会发到外部的事（推送到远程仓库、部署、发送邮件或消息、发布、付款），也不要删除工作文件夹之外的文件；如有需要，写在回答里。在工作文件夹内照常修改和创建。",
  "이미 밖으로 보낸 것은 다시 하지 마.": "已经发到外部的，不要再做一次。",
  "\"{label}\" 단계에서 {name}이(가) 오류로 끝났어.": "{name} 在“{label}”阶段以错误结束。",
  "\"{label}\" 단계의 {id}({name})이(가) 오류로 끝났어. 기다린 앞 카드 {ids}은(는) 결과 없이 끝났어.": "“{label}”阶段的 {id}（{name}）以错误结束。它等待的前面卡片 {ids} 没有结果就结束了。",
  "\"{label}\" 단계의 {id}({name})이(가) 오류로 끝났어.": "“{label}”阶段的 {id}（{name}）以错误结束。",
  "{id}: 기다린 앞 카드 {ids}이(가) 결과 없이 끝났고, 이 카드도 끝나지 못했어({status}).": "{id}：它等待的前面卡片 {ids} 没有结果就结束了，这张卡片也没能完成（{status}）。",
  "조사 담당 {name}의 AI({ai}) 사용량 한도가 거의 다 차서 \"{label}\" 단계에서는 회의 중 조사를 껐어.": "调查负责人 {name} 的 AI（{ai}）用量快到上限，所以在“{label}”阶段关闭了会议中的调查。",
  "확인 못 함: 조사 담당 AI의 사용량 한도가 거의 다 차서 회의 중 조사를 껐어.": "未能确认：调查负责人的 AI 用量快到上限，所以关闭了会议中的调查。",
  "{name}의 답에 이 대목({part})이 받지 않는 블록 {blocks}이(가) 있어서 그 블록은 읽지 않았어.": "{name} 的回答中有这一步（{part}）不接受的块 {blocks}，所以没有读取该块。",
  "{name}: 요청한 AI는 {asked}인데 {ran}(으)로 돌았어(이유: {why}).": "{name}：请求的是 {asked}，实际用 {ran} 运行（原因：{why}）。",
  "{name}의 AI({ai}) 사용량 한도가 거의 다 차서 인수인계 메모 먼저 쓰기를 건너뛰었어. 한도가 줄면 부가 일부터 멈춰.": "{name} 的 AI（{ai}）用量快到上限，所以跳过了先写交接备忘。限额紧张时先停附加工作。",
  "하루 예산 다 씀": "每日预算已用完",
  "지운 계정": "已删除的账号",
  "{name}: 요청한 AI({asked}) 그대로 돌았어(이유: {why}).": "{name}：按请求的 AI（{asked}）运行（原因：{why}）。",
  "회의 중 조사를 끈 까닭이 풀려서 \"{label}\" 단계에서 다시 켰어.": "关闭会议中调查的原因已解除，所以在“{label}”阶段重新开启了。",
